	c.view, c.err = pACStudio, ErrExists
	v, _ = Adopt(context.Background(), c, "studio", "/s", "https://github.com/o/s", "go")
	testhelp.Equal(t, "example 3 variant view returned with the error", v, pACStudio)
}
