// pHHAdopter adds AdoptProject to the fake Control and records its four arguments.
type pHHAdopter struct {
	*pHHFake
	adopts [][4]string
	aview  control.ProjectView
	aerr   error
}

func (a *pHHAdopter) AdoptProject(ctx context.Context, name, dir, repoURL, language string) (control.ProjectView, error) {
	a.adopts = append(a.adopts, [4]string{name, dir, repoURL, language})
