// pRTFake implements control.Control; each call is recorded as "<Method> <project>".
type pRTFake struct {
	calls []string
}

func (f *pRTFake) rec(m, p string) { f.calls = append(f.calls, m+" "+p) }

func (f *pRTFake) Projects() []control.ProjectView { f.rec("Projects", ""); return nil }
